[CmdletBinding()]param()
$ErrorActionPreference='Stop';Set-StrictMode -Version 2.0;. (Join-Path $PSScriptRoot 'PortableSnapshot.Catalog.ps1')
$temp=Join-Path $env:TEMP ('snapshot-positive-'+[guid]::NewGuid().ToString('N'));$passed=0
function Hash-Tree([string]$Path){(@(Get-ChildItem $Path -File -Recurse|Sort-Object FullName|ForEach-Object{"$($_.FullName.Substring($Path.Length)):$((Get-FileHash $_.FullName).Hash)"})-join'|')}
try{New-Item -ItemType Directory -Path $temp|Out-Null;$a=Join-Path $temp 'a';$b=Join-Path $temp 'b';& (Join-Path $PSScriptRoot 'New-SyntheticPortableSnapshotCatalog.ps1') -Destination $a|Out-Null;& (Join-Path $PSScriptRoot 'New-SyntheticPortableSnapshotCatalog.ps1') -Destination $b|Out-Null;if((Hash-Tree $a)-cne(Hash-Tree $b)){throw 'SNAPSHOT_NOT_DETERMINISTIC'};$passed++;Test-PortableSnapshotCatalog $a|Out-Null;$passed++;$catalog=Read-PortableJson (Join-Path $a 'catalog.json');if(@($catalog.customers).Count-ne2){throw 'SNAPSHOT_CUSTOMER_COUNT_INVALID'};$passed++;if(@($catalog.customers[0].projects).Count-ne2-or@($catalog.customers[1].projects).Count-ne1){throw 'SNAPSHOT_PROJECT_CARDINALITY_INVALID'};$passed++;foreach($c in @($catalog.customers)){foreach($p in @($c.projects)){$release=Read-PortableJson (Join-Path $a ($p.release_manifest_path-replace'/',[IO.Path]::DirectorySeparatorChar));if($release.transports.filesystem.payload_sha256-cne$release.transports.http.payload_sha256){throw 'SNAPSHOT_TRANSPORT_NOT_EQUAL'};$passed++}};if($passed-ne7){throw "SNAPSHOT_POSITIVE_COUNT_INVALID:$passed"};Write-Host "PASS: $passed Snapshot-, Zwei-Kunden-, Determinismus- und Transportpruefungen."}finally{if(Test-Path $temp){Remove-Item $temp -Recurse -Force -ErrorAction SilentlyContinue}}
